import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios';

function Homepage() {
  const [input, setInput] = useState('');
  const [result, setResult] = useState(null);

  const handleCheck = async () => {
    try {
      const response = await axios.post('http://localhost:5001/api/check', { content: input });
      setResult(response.data);
    } catch (error) {
      console.error('Error:', error);
      setResult({ error: 'Failed to analyze content' });
    }
  };

  return (
    <div className="homepage">
      <h1>Welcome to TruthGuard</h1>
      <p>Verify the authenticity of your content</p>
      <div className="content-checker">
        <textarea
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="Enter content to verify..."
          rows="4"
        />
        <button onClick={handleCheck}>Verify Content</button>
        {result && (
          <div className="result">
            <h3>Analysis Result:</h3>
            <pre>{JSON.stringify(result, null, 2)}</pre>
          </div>
        )}
      </div>
      <Link to="/dashboard">Go to Dashboard</Link>
    </div>
  );
}

export default Homepage;
